const items = $input.all();
const rows = items.map(i => i.json);

const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

const weekData = rows.filter(r => new Date(r.date) >= oneWeekAgo);

const summary = {};
for (const row of weekData) {
  const name = row.employeeName || row.name;
  if (!summary[name]) {
    summary[name] = { name, present: 0, absent: 0, late: 0, totalDays: 0 };
  }
  summary[name].totalDays++;
  const status = (row.status || '').toLowerCase();
  if (status === 'present') summary[name].present++;
  else if (status === 'absent') summary[name].absent++;
  else if (status === 'late') summary[name].late++;
}

const report = Object.values(summary).map(s => ({
  ...s,
  attendanceRate: Math.round((s.present / s.totalDays) * 10000) / 100
}));

const totalEmployees = report.length;
const avgAttendance = Math.round(report.reduce((sum, r) => sum + r.attendanceRate, 0) / totalEmployees * 100) / 100;

return report.map(r => ({ json: { ...r, weekEnding: new Date().toISOString().split('T')[0], avgTeamAttendance: avgAttendance } }));
